-- Dumping data for table siaganow.news_articles: ~0 rows (approximately)
INSERT INTO `news_articles` (`id`, `title`, `slug`, `category`, `summary`, `body`, `image_path`, `image_alt`, `source_name`, `source_url`, `is_simulation`, `publication_status`, `author_user_id`, `published_at`, `created_at`, `updated_at`) VALUES
	(1, 'BNPB: Banjir Jabodetabek Maret 2025 Rendam 72.050 Rumah', 'bnpb-banjir-jabodetabek-maret-2025-rendam-72050-rumah', 'Banjir', 'Buletin BNPB Maret 2025 merekap 72.050 rumah terendam banjir di Jabodetabek dan 259.883 jiwa terdampak serta mengungsi. Ini adalah rekap historis, bukan kondisi banjir terkini.', 'Banjir melanda sejumlah wilayah Jakarta, Bogor, Depok, Tangerang, dan Bekasi pada Maret 2025 setelah hujan berintensitas tinggi. Buletin Info Bencana BNPB Maret 2025 menyebut bahwa selama bulan tersebut, 72.050 unit rumah di Jabodetabek terendam. Buletin yang sama mencatat 259.883 jiwa mengalami dampak dan mengungsi.\n\nAngka ini merupakan rekap untuk periode Maret 2025. Angka tersebut tidak menggambarkan kondisi banjir saat ini dan tidak boleh digunakan sebagai peringatan aktif. Untuk informasi terkini, periksa pengumuman resmi BNPB, BPBD setempat, dan BMKG.\n\nFoto dokumentasi: banjir di Jatiasih, Kota Bekasi, 4 Maret 2025. Kredit foto pada buletin: Pesawat NIR Awak Tim Pusdatinkomben.', 'news/3FnQMiJIOSOa5Vzz3rX6YbUOYq8PU15aHkqUctel.jpg', 'Foto udara banjir di kawasan permukiman Jatiasih, Kota Bekasi, pada 4 Maret 2025. Foto: Pesawat NIR Awak Tim Pusdatinkomben.', 'BNPB — Buletin Info Bencana Maret 2025', 'https://bnpb.go.id/storage/app/media/Buletin%20Info%20Bencana/2025%20Buletin%20Info%20Bencana/2025%20Maret/Buletin%20Info%20Bencana%20Maret%202025.pdf', 0, 'published', 2, '2026-11-15 05:50:08', '2026-11-15 05:50:08', '2026-11-15 05:50:08');

